{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        mr = max(core_dist[u], core_dist[v], d)
        if u > v:
            u, v = v, u
        edges.append((mr, u, v))

    # Sort by weight, then by endpoints
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find (Disjoint Set)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    expected_edges = len(nodes) - 1

    for mr, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mr])
            total_weight += mr
            if len(mst_edges) == expected_edges:
                break

    if len(mst_edges) != expected_edges:
        raise ValueError("Graph is disconnected; cannot form MST")

    return {
        "mst_edges": mst_edges,
        "total_weight": total_weight
    }"
}
